def main():
    for lang, extra, idx in (('pt_br', EXTRA_PT, 0), ('en_us', EXTRA_EN, 1)):
        path = LANG + lang + '.json'
        data = json.load(open(path, encoding='utf-8'))
        # remove chaves antigas de perks/skills que não existem mais
        for k in list(data):
            if k.startswith('perk.leveledworld.') or k == 'skill.leveledworld.armor' or k == 'skill.leveledworld.armor.desc':
                del data[k]
        for skill, (pt, en, dpt, den) in SKILLS.items():
            data[f'skill.leveledworld.{skill}'] = pt if idx == 0 else en
            data[f'skill.leveledworld.{skill}.desc'] = dpt if idx == 0 else den
        for skill, perks in PERKS.items():
            for perk, names in perks.items():
                data[f'perk.leveledworld.{skill}.{perk}'] = names[0 if idx == 0 else 2]
                data[f'perk.leveledworld.{skill}.{perk}.desc'] = names[1 if idx == 0 else 3]
        data.update(extra)
        json.dump(data, open(path, 'w', encoding='utf-8'), ensure_ascii=False, indent=2)
        open(path, 'a').write('\n')
        print(lang, len(data), 'chaves')


if __name__ == '__main__':
    main()
